idx_to_char = {i: ch for i, ch in enumerate(chars)}


class GeometricDataset(torch.utils.data.Dataset):
	"""Load geometric contact records generated by ``Models/data.py``."""

	def __init__(self, path):
		self.path = Path(path)
		if not self.path.exists():
			raise FileNotFoundError(f"Geometric dataset not found: {self.path}")
		if not self.path.is_dir():
			raise ValueError(f"Geometric dataset must be a directory: {self.path}")

		self.files = sorted(
			file_path for file_path in self.path.rglob("*.npy")
			if not file_path.stem.endswith("_typo"))
		if not self.files:
			raise ValueError(f"Geometric dataset directory is empty: {self.path}")

	def __len__(self):
		return len(self.files)

	def __getitem__(self, idx):
		file_path = self.files[idx]
		_, separator, label = file_path.stem.partition("_")
		if not separator or not label:
			raise ValueError(
				f"Geometric record filename must contain a participant and label: {file_path}")
		label = label.lower()
		if any(char not in char_to_idx for char in label):
			raise ValueError(f"Geometric record has an invalid label: {file_path}")

		try:
			features = np.load(file_path, allow_pickle=False)
		except (OSError, ValueError) as exc:
			raise ValueError(
				f"Could not load numeric geometric features from {file_path}") from exc

		if features.ndim != 2 or features.shape[0] == 0:
			raise ValueError(
				f"Geometric record {idx} must contain at least one feature frame")
		if not np.issubdtype(features.dtype, np.number):
			raise ValueError(f"Geometric record {idx} must contain numeric features")

		labels = torch.tensor([char_to_idx[char] for char in label], dtype=torch.long)
		return labels, torch.from_numpy(features.astype(np.float32, copy=False))


class TestGeometricDataset(torch.utils.data.Dataset):
	"""
	Data is in the format
	sentence, list of [normalised x coordinates], list of [normalised y coordinates]
	"""
	def __init__(self, csv_path):
		self.path = Path(csv_path)
		self.labels = []
		self.features = []

		with self.path.open("r", newline="", encoding="utf-8") as file:
			for row in csv.DictReader(file):

			# Each row contains comma-separated coordinates and its target character string.

				sentence = row['sentence'][:]
				x_list = np.asarray(row['x_list'].strip("[]").split(','), dtype=np.float32)
				y_list = np.asarray(row['y_list'].strip("[]").split(','), dtype=np.float32)
				if len(x_list) != len(y_list) or len(x_list) != len(sentence):
					raise ValueError(
						f"Row has mismatched lengths: "
						f"x={len(x_list)}, y={len(y_list)}, sentence={len(sentence)}"
					)

				coordinates = torch.tensor(np.column_stack((x_list, y_list)), dtype=torch.float32)
				char_list = torch.tensor([char_to_idx[char] for char in sentence], dtype=torch.long)

				self.labels.append(char_list)
				self.features.append(coordinates)
				

	def __getitem__(self, idx):
		return self.labels[idx], self.features[idx]

	def __len__(self):
		return len(self.labels)

def pad_variable(batch):
	# Each sample is (character labels, (x, y) features); models consume features first.
	sorted_batch = sorted(batch, key=lambda x: x[0].shape[0], reverse=True)
	labels = [sample[0] for sample in sorted_batch]
	features = [sample[1] for sample in sorted_batch]
	labels_padded = torch.nn.utils.rnn.pad_sequence(
		labels,
		batch_first=True,
		padding_value=-100,
	)
	features_padded = torch.nn.utils.rnn.pad_sequence(features, batch_first=True)

	return labels_padded.long(), features_padded

